package project.init.framework.utils;import java.sql.Timestamp;import java.time.Instant;import java.time.ZonedDateTime;import java.time.temporal.ChronoUnit;public class DateTimeUtils {    private DateTimeUtils() {    }    public static Instant getCurrentTimeUTC() {        return ZonedDateTime.now(Constants.DEFAULT_ZONE_ID).toInstant().truncatedTo(ChronoUnit.SECONDS);    }    public static Timestamp getCurrentTimestamp() {        return new Timestamp(System.currentTimeMillis());    }}